-- Description:	SQL Server Query that fix Control Message Check Missing Restart Msg 
--              in Spool table
-- For:         BizTalk Server 2004
-- =======================================================================================

-- ********************************************************
-- For 2004 we will need the following 1 control message
-- ********************************************************

-- Inserting Restart Message for use in service recovery
IF (SELECT COUNT (*) FROM Spool WHERE uidMessageID = N'61EAA7FC-AC85-42d9-BF3E-1BED258B82BE') = 0
BEGIN
	INSERT INTO Spool (uidMessageID, nNumParts, nCounter, imgContext) VALUES (N'61EAA7FC-AC85-42d9-BF3E-1BED258B82BE', 0, 0, )

	INSERT INTO MessageRefCountLogTotals (uidMessageID, snRefCount) VALUES (N'61EAA7FC-AC85-42d9-BF3E-1BED258B82BE', 1)
END
GO